import type { Claim } from './types';
export type { Claim, ClaimStatus } from './types';

/**
 * Every number and physical statement used on the page, with its source. `status` is set from the
 * independent verification log (docs/verification.md): auditors who had not seen this site opened each
 * cited source and checked the statement against it. Where an auditor found a discrepancy, the statement
 * below is the corrected one and `note` records what changed.
 */
export const CLAIMS: Claim[] = [
  // ───────────── section 1: single neuron ─────────────
  { id: 'quasistatic', section: 1, statement: 'At EEG frequencies the head is a purely resistive (quasi-static) volume conductor: for brain tissue with σ ≈ 0.3 S/m and relative permittivity ~10⁵ the ratio of capacitive to ohmic current at 100 Hz is 2πfε/σ ≈ 2×10⁻³, and in vivo cortical impedance is frequency-independent and predicted by a purely resistive conductor.', refs: ['hamalainen1993', 'logothetis2007', 'malmivuo1995', 'plonsey1967'], status: 'verified' },
  { id: 'monopole', section: 1, statement: 'The potential of a point current source I in an infinite homogeneous conductor of conductivity σ is Φ = I / (4πσr) (Malmivuo & Plonsey eq. 8.7).', refs: ['malmivuo1995'], status: 'verified' },
  { id: 'dipole', section: 1, statement: 'The potential of a current dipole of moment p is Φ = p cosθ / (4πσr²) (eq. 8.15); the dipole field falls as 1/r² whereas the monopole field falls as 1/r.', refs: ['malmivuo1995'], status: 'verified' },
  { id: 'sigma-gray', section: 1, statement: 'Grey-matter conductivity: 0.33 S/m is the classical modelling value (0.3 S/m for brain tissue in Hämäläinen et al.; 0.333 S/m for grey matter in the Ramon et al. finite-element table). The 2019 meta-analysis gave a weighted mean of 0.47 ± 0.24 S/m across 16 grey-matter studies (66 values; reported range 0.06–2.47 S/m), revised to 0.38 ± 0.16 S/m in its 2021 correction.', value: 0.33, units: 'S/m', range: [0.06, 2.47], refs: ['mccann2019', 'mccann2021', 'ramon2006', 'hamalainen1993'], status: 'verified', note: 'Audit: Hämäläinen’s 0.3 S/m is a brain-tissue value used in a quasi-static validity estimate; the 2021 correction (0.38 S/m) was added after the audit flagged it.' },
  { id: 'epsc', section: 1, statement: 'A unitary connection between thick-tufted layer-5 pyramidal cells (rat somatosensory slices) produces an excitatory postsynaptic potential of 1.3 ± 1.1 mV (range 0.15–5.5 mV) with an inferred quantal peak conductance of 1.5–5.5 nS (mean 3 nS) at −60 mV.', refs: ['markram1997'], status: 'verified' },
  { id: 'cell-current', section: 1, statement: 'Order-of-magnitude current used as the slider default: a burst-envelope dipole of 0.4–0.9 pA·m over an apical trunk of ~0.4–0.6 mm gives ~1–2 nA of net membrane current; for comparison, a single synaptic contact with a quantal conductance of 1.5–5.5 nS passes on the order of 100–300 pA at a ~60 mV driving force.', value: 1, units: 'nA', refs: ['murakami2006', 'galloni2020', 'markram1997'], status: 'derived', note: 'Derived from the cited moment, trunk length and conductance; none of the sources states the current directly. Murakami & Okada’s envelope arises from a somatically stimulated burst, not a synaptic one.' },
  { id: 'dipole-length', section: 1, statement: 'Mean apical trunk length (soma to main bifurcation) of layer-5 pyramidal neurons is 409 ± 64 µm in mouse V1 and 313 ± 65 µm in V2m; in the thick-tufted (Hay et al. 2011) model used in the same study the main bifurcation lies ~620 µm from the soma. The slider default of 500 µm lies in this range.', value: 500, units: 'µm', range: [313, 620], refs: ['galloni2020'], status: 'verified', note: 'Corrected after audit: an earlier version quoted 685–885 µm, which is the model’s dendritic Ca²⁺ hot zone, not the trunk length.' },
  { id: 'spike-noise-floor', section: 1, statement: 'Neuropixels silicon probes have a noise floor of about 5 µV rms in the action-potential band (5.1 ± 0.6 µV in saline; 5.5–6.6 µV rms across the four probe configurations) and 8–13 µV rms in the LFP band.', value: 5, units: 'µV rms', range: [5.1, 6.6], refs: ['jun2017'], status: 'verified', note: 'Corrected after audit: LFP-band noise given as a range (8–13 µV) rather than “about 9 µV”.' },
  { id: 'cortex-layers', section: 1, statement: 'Human cerebral cortex is 1 to 4.5 mm thick with an overall average of about 2.5 mm (histological values quoted by Fischl & Dale). In human temporal cortex layer 4 ends about 1.6 mm below the pia and the grey/white border lies at about 2.8 mm; layer 5 begins about 1.5 mm below the pia, and human layer-5 pyramidal neurons were recorded 1.5 to 2.2 mm below it. The drawings place the cell body 1.6 mm below the surface.', value: 1.6, units: 'mm', range: [1.5, 2.2], refs: ['fischl2000', 'mohan2015', 'beaulieu2018'], status: 'verified', note: 'Audit: the thickness figures are histological values quoted in Fischl & Dale’s introduction, not their MRI result, and the soma depths are now taken from Beaulieu-Laroche et al. (1.5–2.2 mm); a Kalmbach et al. 2021 figure that the auditor could not access was dropped.' },
  { id: 'henze-50um', section: 1, statement: 'In urethane-anaesthetised rat hippocampal CA1 in vivo, extracellular spikes recorded within 50 µm of the soma are ≥ 60 µV (units as large as ~600 µV were observed).', value: 60, units: 'µV', refs: ['henze2000'], status: 'verified' },
  { id: 'henze-140um', section: 1, statement: 'Beyond about 140 µm from the soma no extracellular spike could be distinguished from background noise even with spike-triggered averaging.', value: 140, units: 'µm', refs: ['henze2000'], status: 'verified' },
  { id: 'spike-decay', section: 1, statement: 'Modelled extracellular spike amplitude decays as 1/rⁿ with 1 ≤ n ≤ 2 close to the soma and n ≥ 2 far away, and spikes are low-pass filtered with distance.', refs: ['pettersen2008'], status: 'verified' },
  { id: 'lfp-reach', section: 1, statement: 'For uncorrelated synaptic activity the local field potential represents cells within a radius of a few hundred micrometres; with correlated activity the generating region grows to the spatial extent of the correlated activity.', refs: ['linden2011'], status: 'verified', note: 'Verified from the abstract (full text paywalled).' },
  { id: 'single-cell-moment', section: 1, statement: 'In realistic compartmental models a layer-5 pyramidal cell produces a current dipole of 0.41–0.90 pA·m (directed away from the pia) during the slow envelope of a burst, with spike components of −0.78 to +2.97 pA·m; a layer-2/3 pyramidal cell gives 0.29 pA·m (envelope) and 0.47 pA·m (spike).', value: 0.5, units: 'pA·m', range: [0.41, 0.9], refs: ['murakami2006'], status: 'verified' },
  { id: 'psp-moment', section: 1, statement: 'A single postsynaptic potential produces a current dipole of about 20 fA·m, so about a million simultaneously active synapses are needed for a typical 10 nA·m evoked-response dipole.', value: 20, units: 'fA·m', refs: ['hamalainen1993'], status: 'verified' },
  { id: 'ephaptic', section: 1, statement: 'Applied fields of ≤ 0.5 mV/mm modulate slow-oscillation network activity in cortical slices (sine-wave fields of 1–4 mV/mm also significant), and weak fields entrain the spiking of individual cortical neurons while polarising the soma by less than 0.5 mV, most effectively below 8 Hz.', value: 0.5, units: 'mV/mm', refs: ['frohlich2010', 'anastassiou2011'], status: 'verified', note: 'Corrected after audit: the Anastassiou full text is paywalled, so only its abstract-level statements are used; the earlier 0.74 mV/mm figure was dropped.' },
  // ───────────── section 2: populations ─────────────
  { id: 'superposition', section: 2, statement: 'Extracellular potentials from multiple current sinks and sources combine linearly by superposition (for an ohmic, homogeneous medium); all volume conductors in bioelectricity are assumed linear, consistent with experiment.', refs: ['buzsaki2012', 'malmivuo1995'], status: 'verified' },
  { id: 'variances-add', section: 2, statement: 'In population models of the local field potential, uncorrelated single-cell contributions add in variance (so amplitude grows as √N) whereas fully correlated contributions add in amplitude (∝ N); with correlated input the population signal no longer saturates with population size.', refs: ['leski2013', 'linden2011'], status: 'verified', note: 'The √N / N exponents are the arithmetic consequence of the source’s “variances add” versus “amplitudes add”.' },
  { id: 'open-closed', section: 2, statement: 'Spatial alignment of neurons and temporal synchrony of their currents are the two most important determinants of extracellular field strength; pyramidal cells with long, thick apical dendrites oriented perpendicular to the cortical surface generate strong dipoles (open fields), whereas spherically symmetric cells tend toward closed fields that cancel at a distance, and populations of stellate cells may sum to less than the linear sum of their dipoles because of their variable dendritic geometry.', refs: ['buzsaki2012', 'murakami2006', 'kirschstein2009'], status: 'verified' },
  { id: 'psp-dominate', section: 2, statement: 'Synaptic currents last tens of milliseconds, overlap in time and are often the most important source of extracellular current; the strongest action-potential fields last under 2 ms and nearby neurons rarely spike synchronously within such windows (although synchronous spiking can still contribute to high-frequency components), and a propagating action potential is a current quadrupole whose field falls off as 1/r³, faster than a dipole’s 1/r².', refs: ['buzsaki2012', 'hamalainen1993'], status: 'verified', note: 'Duration and quadrupole statements are from Hämäläinen et al.; the high-frequency caveat was added after the audit.' },
  { id: 'cells-for-10nam', section: 2, statement: 'A typical MEG/EEG source has an equivalent current dipole of about 10 nA·m, caused by the synchronous activity of probably tens of thousands of neurons; modelled pyramidal-cell bursts become detectable when 10,000–50,000 cells are synchronously active.', value: 10, units: 'nA·m', range: [10000, 50000], refs: ['hamalainen1993', 'murakami2006'], status: 'verified' },
  { id: 'neuron-density', section: 2, statement: 'Rockel, Hiorns & Powell counted ~110 neurons in a 30-µm-wide strip through the cortical depth (750 µm² of surface), i.e. about 147,000 neurons under 1 mm² of cortical surface (primate binocular area 17 excepted, ~2.5×); a 2013 stereological replication confirmed the uniformity, while Herculano-Houzel et al. report up to three-fold variation across primate species.', value: 147000, units: 'neurons/mm²', refs: ['rockel1980', 'herculano2008', 'carlo2013'], status: 'verified', note: 'Verified from abstracts; the 147,000/mm² conversion is stated by Herculano-Houzel et al.' },
  { id: 'pyramidal-fraction', section: 2, statement: 'About one in five neocortical neurons is GABAergic (inhibitory) across many areas and species, so roughly 80% are excitatory (glutamatergic) neurons, of which pyramidal cells are the main class.', value: 0.8, refs: ['sahara2012'], status: 'verified' },
  { id: 'tao-area', section: 2, statement: 'With simultaneous scalp and intracranial EEG in 16 temporal-lobe-epilepsy patients, intracranial spikes involving < 6 cm² of cortex were never seen on the scalp, only 10% of spikes with < 10 cm² produced scalp spikes, and 90% of spikes with > 10 cm² did; synchronous (or at least temporally overlapping) activation of 10–20 cm² of gyral cortex was common.', value: 10, units: 'cm²', range: [6, 20], refs: ['tao2005'], status: 'verified' },
  { id: 'area-rule', section: 2, statement: 'Rule of thumb from the tutorial literature: roughly 6–10 cm² of contiguous, synchronously active cortex is needed for a potential recognisable at the scalp, and scalp EEG is a spatiotemporally smoothed version of the local field potential integrated over 10 cm² or more.', range: [6, 10], units: 'cm²', refs: ['nunez2019', 'buzsaki2012'], status: 'verified', note: 'Split from the Tao et al. claim after the audit noted that these secondary sources do not contain Tao’s percentages.' },
  { id: 'glia-slow', section: 2, statement: 'Glial membrane-potential changes can contribute to extracellular potentials, but the glial syncytium is thought to contribute mainly to slow and infraslow (< 0.1 Hz) field patterns.', value: 0.1, units: 'Hz', refs: ['buzsaki2012'], status: 'verified', note: 'Corrected after audit: “only” → “mainly” (the source hedges with “may”).' },
  { id: 'ca-spike-moment', section: 2, statement: 'Dendritic Ca²⁺ spikes are large (10–50 mV) and long-lasting, so under some circumstances their share of extracellular events can be substantial; separately, in single-cell models the Na⁺ action-potential component of a layer-5 pyramidal cell’s dipole ranges from −0.78 to 2.97 pA·m across cells, versus 0.41–0.90 pA·m for the slow burst envelope.', value: 2.97, units: 'pA·m', refs: ['buzsaki2012', 'murakami2006'], status: 'verified', note: 'Corrected after audit: the 2.97 pA·m figure is a somatic action potential in the model, not a dendritic Ca²⁺ spike.' },
  { id: 'sync-thalamic', section: 2, statement: 'During relaxed wakefulness the EEG shows alpha (8–13 Hz) activity on which the thalamus is a strong influence; two thalamic cellular mechanisms, high-threshold burst firing in a subset of thalamocortical neurons and the interconnection of that subset by gap junctions, combine to generate locally synchronised alpha activity, and the same machinery yields theta (2–7 Hz) when the thalamocortical neurons are less depolarised.', refs: ['hughes2005'], status: 'verified', note: 'Audit: supported by the abstract.' },
  { id: 'sync-inhibition', section: 2, statement: 'Gamma oscillations (30–90 Hz) are generated by networks of inhibitory interneurons acting through GABA-A synapses; perisomatic inhibition by fast-spiking basket cells is the key synchronising ingredient, a network of mutually connected interneurons needs only mutual inhibition, the GABA-A time constant and enough drive to oscillate at gamma, and (citing Lytton & Sejnowski’s 1991 modelling) perisomatic inhibitory potentials synchronise neurons substantially more effectively than dendritic excitatory ones.', refs: ['buzsakiwang2012'], status: 'verified', note: 'Audit: wording aligned to the source (“substantially more effective”, a cited modelling result).' },
  { id: 'sync-waves', section: 2, statement: 'Cortical activity also propagates as travelling waves at two scales carried by distinct axon populations: mesoscopic waves within one cortical area at speeds consistent with unmyelinated layer 2/3 horizontal fibres (0.1–0.8 m/s), and macroscopic waves spanning centimetres at 1–10 m/s, within the range of myelinated white-matter conduction; human ECoG sleep-spindle waves cluster at 2–5 m/s.', refs: ['muller2018'], status: 'verified', note: 'Audit: the 2–5 m/s figure applies to sleep-spindle waves only; an earlier wording that extended it to alpha waves was removed.' },
  { id: 'oscillations-synchrony', section: 2, statement: 'Mammalian forebrain networks show oscillatory bands spanning about 0.05–500 Hz; the period of an oscillation is constrained by the size of the neuronal pool engaged in each cycle, with very large networks recruited during slow oscillations.', refs: ['buzsaki2004'], status: 'verified' },
  { id: 'inhibitory-contrib', section: 2, statement: 'Inhibitory (GABA-A) currents, often assumed to add little, can generate substantial transmembrane currents when the membrane is depolarised in actively spiking neurons; spike-triggered unitary field potentials in human and monkey cortex indicate that the LFP reflects primarily inhibitory-neuron activity, inferred from timing and polarity (amplitudes of inhibitory and excitatory unitary fields were similar).', refs: ['buzsaki2012', 'telenczuk2017'], status: 'verified', note: 'Conditions added after the audit.' },
  { id: 'orientation', section: 2, statement: 'EEG sensitivity depends only weakly on source orientation (median ratio of weakest to strongest orientation 0.63; 95% of cortical locations above 0.42), whereas MEG is nearly blind to one orientation (median 0.06) and insensitive to radial sources.', value: 0.63, refs: ['ahlfors2010'], status: 'verified' },
  // ───────────── section 3: head layers ─────────────
  { id: 'mccann-meta', section: 3, statement: 'Meta-analysis of reported human head-tissue conductivities (weighted means, 2019): scalp 0.41 S/m, whole skull 0.016 S/m (0.02 in the abstract), spongy bone 0.050, compact bone 0.0046 S/m, brain-to-skull ratio 50.4 (reported range 17.9–290). Its 2021 correction revised the brain values to CSF 1.74, grey matter 0.38 and white matter 0.15 S/m (originally 1.71, 0.47 and 0.22).', refs: ['mccann2019', 'mccann2021'], status: 'verified', note: 'Corrected after audit: the 2021 correction was added and its values adopted.' },
  { id: 'sigma-csf', section: 3, statement: 'Human cerebrospinal fluid conductivity measured in 7 patients is 1.79 S/m at 37 °C (1.45 S/m at 25 °C) across 10 Hz–10 kHz; the meta-analytic weighted mean is 1.74 S/m (2021 correction; 1.71 in the 2019 paper).', value: 1.79, units: 'S/m', range: [1.0, 2.51], refs: ['baumann1997', 'mccann2019', 'mccann2021'], status: 'verified' },
  { id: 'sigma-skull', section: 3, statement: 'Whole-skull conductivity: about 0.015 S/m from in vivo and in vitro measurements (brain:skull ≈ 15:1); meta-analytic weighted mean 0.016 S/m (reported as 0.02 ± 0.02 in the abstract); live skull layers 16–41 mS/m (spongiform), 5.4–7.2 mS/m (outer compact) and 2.8–10.2 mS/m (inner compact); skull pieces removed at surgery gave 32–80 mS/m.', value: 0.015, units: 'S/m', range: [0.0028, 0.08], refs: ['oostendorp2000', 'mccann2019', 'akhtari2002', 'hoekema2003'], status: 'verified' },
  { id: 'skull-brain-ratio', section: 3, statement: 'A brain-to-skull conductivity ratio of 80 was the commonly used value in source localisation; in vivo estimates give about 15 (current injection, Oostendorp et al.), 25 ± 7 (range 18–34) from simultaneous scalp and subdural recordings, and 20–50 from electrical impedance tomography; the meta-analytic weighted mean is 50.4 ± 39 (10 studies).', value: 25, range: [15, 80], refs: ['lai2005', 'goncalves2003', 'oostendorp2000', 'mccann2019'], status: 'verified', note: 'Corrected after audit: the attribution of the value 80 to Rush & Driscoll (1968) was removed because it does not appear in the accessible text of the cited sources.' },
  { id: 'sigma-scalp', section: 3, statement: 'Scalp conductivity: meta-analytic weighted mean 0.41 S/m (realistic values 0.25–0.435 S/m after excluding outliers); 0.435 S/m in the Ramon et al. finite-element table; the Nunez et al. four-sphere model assumes scalp and brain equal.', value: 0.41, units: 'S/m', range: [0.25, 0.435], refs: ['mccann2019', 'ramon2006', 'nunez2019'], status: 'verified' },
  { id: 'sigma-dura', section: 3, statement: 'Dura mater conductivity used in a dura-inclusive finite-element head model is 0.06 S/m (literature bounds 0.02–0.1 S/m, about 0.04× CSF); the meta-analysis found insufficient data for dura (its single tabulated value is 0.461 S/m). Including the dura layer reduced simulated scalp potentials by about 20% (up to 40% at the peak location).', value: 0.06, units: 'S/m', range: [0.02, 0.1], refs: ['ramon2014', 'mccann2019'], status: 'verified', note: 'Ramon et al.’s own abstract misprints the dura/CSF values; the Methods/Table values are used here.' },
  { id: 'thickness-skull', section: 3, statement: 'Mean calvarial thickness across 40 frontal, parietal and occipital sites in 281 dry skulls is 6.32 mm (site means 5.3–7.5 mm); age was not a significant predictor.', value: 6.32, units: 'mm', range: [5.3, 7.5], refs: ['moreira2006'], status: 'verified' },
  { id: 'thickness-scalp', section: 3, statement: 'Normal full scalp thickness at the vertex on ultrasound is about 5–6 mm (stated as the normal range in a two-patient clinical case report); the Nunez et al. four-sphere model implies a 6 mm scalp shell (radii 8.6 and 9.2 cm).', value: 5.5, units: 'mm', range: [5, 6], refs: ['khalil2024', 'nunez2019'], status: 'partially', note: 'Low-confidence source for the normative value; no normative study was located.' },
  { id: 'thickness-csf', section: 3, statement: 'The Nunez et al. four-sphere model uses radii of 8.0 and 8.1 cm for brain and CSF, i.e. a 1 mm CSF layer; the occipital CSF layer thins by about 30% when a subject moves from prone to supine, raising occipital EEG power for spatially incoherent high-frequency activity by about 80% on average (several-fold in some subjects).', value: 1, units: 'mm', refs: ['nunez2019', 'rice2013'], status: 'verified', note: 'Corrected after audit: “high-frequency” restored; radii verified in the open preprint of Nunez et al.' },
  { id: 'thickness-dura', section: 3, statement: 'Cranial dura thickness measured at autopsy over the petrous apex (skull base; 19 of 20 decedents analysed) averages 0.36 mm (0.27–0.46 mm, SD 0.16 mm); convexity dura under the EEG cap was not measured, so the value is an order of magnitude.', value: 0.36, units: 'mm', range: [0.27, 0.46], refs: ['fam2018'], status: 'verified' },
  { id: 'csf-shunt', section: 3, statement: 'The highly conductive CSF channels (shunts) current, lowering peak cortical current density; head models that omit the CSF layer underestimate the half-sensitivity volume by 20% (MRI-based) to 45% (CT-based), and a model without CSF performed worst in source localisation.', refs: ['wendel2008', 'ramon2006'], status: 'verified' },
  { id: 'spatial-lowpass', section: 3, statement: 'The scalp EEG is spatially low-pass filtered by the poorly conducting skull: a four-sphere model predicts that electrodes within 10–12 cm can appear correlated purely through volume conduction, and measured scalp spatial spectra fall off faster than at the pia because of smearing by dura, skull and scalp.', refs: ['srinivasan1998ieee', 'freeman2003'], status: 'verified' },
  { id: 'sphere-model', section: 3, statement: 'A standard analytic EEG forward model is the concentric-sphere head (brain, CSF, skull, scalp with radii 8.0, 8.1, 8.6, 9.2 cm in Nunez et al.); exact series solutions for multilayer spheres are given by de Munck & Peters (1993); Berg & Scherg (1994) give a fast three-dipole approximation, which Zhang (1995) extended to multilayer anisotropic spheres.', refs: ['nunez2019', 'demunck1993', 'berg1994', 'zhang1995'], status: 'verified', note: 'Corrected after audit: Zhang (1995) is an extension of the Berg & Scherg approximation, not an exact series.' },
  { id: 'exterior-potential', section: 3, statement: 'With air treated as a perfect insulator, no current leaves the head and the interior solution is unchanged; the potential in the air is the solution of Laplace’s equation that equals the scalp potential on the surface and vanishes at infinity, so each spherical-harmonic term of degree l continues outward as (R/r)^(l+1), the finer the pattern the faster. For the default source of section 3 (scalp half-width 2.2 cm) the potential on the axis falls to 70% of its scalp value 0.5 cm above the skin, to half at about 1 cm and to a quarter at 3 cm.', refs: ['jackson1999', 'hallez2007'], status: 'derived', note: 'Standard exterior boundary-value problem (exterior solutions of Laplace’s equation: Jackson; zero normal current into the air as the EEG boundary condition: Hallez et al.). The percentages are computed by the page’s own solver (exteriorPotential in src/physics/sphere.ts); the auditor’s independent Legendre calculation for a 2.2 cm half-width pattern gave 71 / 53 / 21%, with the 3 cm value the most shape-sensitive. Wires, the electrode itself and the rest of the body are ignored. Audit: Nunez et al. 2019 was replaced by Hallez et al. 2007, which states the boundary condition.' },
  { id: 'brain-radius', section: 3, statement: 'The Nunez et al. four-sphere model’s brain radius is 8.0 cm.', value: 8.0, units: 'cm', refs: ['nunez2019'], status: 'verified' },
  { id: 'ecog-vs-eeg', section: 3, statement: 'For an isolated macrocolumn-scale cortical dipole the expected cortical-to-scalp potential ratio is about 50–100, while measured spontaneous ECoG/EEG ratios are typically 2–5 (as expected for large synchronous dipole sheets); a textbook gives ~100 µV on the scalp versus 1–2 mV on the brain surface; simultaneous invasive and scalp recordings show invasive signal quality (brain signal relative to blink artefact) 20 to more than 100 times better; in a 144,000-dipole simulation the standard deviation of potentials falls from 22.8 µV on the cortex to 7.7 µV at the outer dura, 5.2 µV at the outer skull and 4.5 µV on the scalp.', range: [2, 100], refs: ['nunez2019', 'malmivuo1995', 'ball2009', 'ramon2014'], status: 'verified' },
  { id: 'eeg-amplitude', section: 3, statement: 'Scalp EEG amplitudes are of the order of 10–100 µV (a textbook puts the scalp EEG at about 100 µV).', value: 50, units: 'µV', range: [10, 100], refs: ['chi2010', 'malmivuo1995'], status: 'verified' },
  // ───────────── section 4: noise ─────────────
  { id: 'alpha-source-chain', section: 5, statement: 'The 20 µV alpha rhythm used in sections 4 and 5 is not an independent choice: in the section 3 head (radial source 2 mm below the cortical surface, default layer thicknesses and conductivities) the page’s own solver gives 0.54 µV at the scalp per nA·m, so 20 µV corresponds to an equivalent dipole of about 37 nA·m, roughly four times the 10 nA·m that Hämäläinen et al. call typical; at 0.29 to 0.90 pA·m per cell (0.5 pA·m used) that is about 4 to 13 × 10⁴ perfectly synchronous pyramidal cells, or 740,000 with a tenth in step, the same order as the tens of thousands of cells associated with a typical source.', value: 37, units: 'nA·m', refs: ['malmivuo1995', 'murakami2006', 'hamalainen1993'], status: 'derived', note: 'Audit: arithmetic confirmed; the 0.54 µV per nA·m is the page’s own four-layer result, not a literature value; Nunez et al. 2019 was dropped from the sources because it supplies none of these numbers; the per-cell range and the comparison with the typical 10 nA·m were added.' },
  { id: 'emg-band', section: 5, statement: 'Surface EMG from striated muscle spans about 20–300 Hz; contamination of resting EEG begins at about 20 Hz (from ~12 Hz with voluntary contraction); muscle artefact at temporal electrodes can reach ~100 µV whereas genuine high-frequency (gamma) neural activity at the scalp can be under 1 µV.', value: 100, units: 'µV', range: [20, 300], refs: ['muthukumaraswamy2013', 'goncharova2003'], status: 'verified' },
  { id: 'emg-level', section: 5, statement: 'Modelling choice: 10 µV rms of muscle noise in the 20–300 Hz band for a relaxed subject at a mid-scalp site, with 100 µV as the clenched-jaw value at a temporal site. Measured support: muscle activity at temporal EEG electrodes can reach about 100 µV against neural gamma below 1 µV; even at central electrodes in resting subjects, scalp EEG above 20 Hz is mostly muscle: Muthukumaraswamy’s reading of Whitham et al. gives about 5 times more power at 40 Hz and 10 times at 80 Hz than under paralysis, and Whitham et al. report 10- to 200-fold differences above 20 Hz; in Huigen et al.’s surface-electrode measurements, resting muscle added negligibly to electrode noise.', value: 10, units: 'µV rms', range: [0, 100], refs: ['muthukumaraswamy2013', 'whitham2007', 'huigen2002'], status: 'assumption', note: 'The relaxed-subject level of 10 µV rms is a chosen value: no source gives an rms figure for a relaxed subject at a mid-scalp site. Audit: measured statements supported; attributions made explicit.' },
  { id: 'emg-topography', section: 5, statement: 'Frontalis and temporalis EMG has a broad spectrum from 0 to > 200 Hz, peaking at 20–30 Hz frontally and 40–80 Hz temporally; even a 15%-of-maximum contraction produces EMG detectable near the vertex above 12 Hz in averaged data (above 8 Hz in some individuals); contamination is greatest at the periphery of the scalp.', range: [20, 80], refs: ['goncharova2003'], status: 'verified' },
  { id: 'blink-amplitude', section: 5, statement: 'Ocular artefact amplitude is generally many times greater than the EEG; uncorrected blinks are typically 100–200 µV at frontal channels, and practical ERP pipelines detect them with ±50–100 µV thresholds on a bipolar eye channel (with ±200 µV absolute and 100–150 µV moving-window thresholds for other large artefacts).', value: 150, units: 'µV', range: [100, 200], refs: ['luck2022', 'jiang2019', 'ronca2024'], status: 'verified', note: 'Corrected after audit: the amplitude now rests on Luck ch. 8 §8.3 (“typically 100–200 µV”) rather than on rejection thresholds.' },
  { id: 'blink-rate', section: 5, statement: 'Eye blinks occur about 12–18 times per minute, with spectral content mainly below ~15 Hz, strongest at frontal electrodes.', value: 15, units: 'per minute', range: [12, 18], refs: ['ronca2024'], status: 'verified', note: 'The review states the blink rate without citing a primary source.' },
  { id: 'common-mode', section: 5, statement: 'The 50/60 Hz common-mode voltage on the body is about 1 mV peak-to-peak with a small isolated battery-powered amplifier, about 10 mV p-p in a typical non-isolated set-up, and up to ~200 mV p-p in a multichannel system with large isolation capacitance; the interference current through the body is typically ~0.5 µA p-p, with ten-fold higher currents found regularly.', value: 10, units: 'mV', range: [1, 200], refs: ['mettingvanrijn1990'], status: 'verified' },
  { id: 'potential-divider', section: 5, statement: 'Differences in electrode impedance or amplifier input impedance convert common-mode voltage into a differential signal (the potential-divider effect): 10 mV p-p common-mode with 20 MΩ input impedance, 20 kΩ electrodes and 50% differences in both gives ~10 µV p-p of mains interference; the usual electrodes show ~20 kΩ at 50 Hz with ~50% inter-electrode differences.', value: 10, units: 'µV', refs: ['mettingvanrijn1990'], status: 'verified' },
  { id: 'cmrr-customary', section: 5, statement: 'A common-mode rejection ratio of 80–90 dB was customary for differential biopotential amplifiers (1990); a driven-right-leg circuit usually reduces common-mode voltage by a further 10–50 dB; 1–10 µV peak-to-peak of interference (under 1% of an ECG) is considered acceptable.', value: 90, units: 'dB', range: [80, 90], refs: ['mettingvanrijn1990'], status: 'verified' },
  { id: 'ads1299', section: 5, statement: 'The ADS1299 EEG front end specifies 1 µV peak-to-peak typical input-referred noise (0.14 µV rms at 250 samples/s, gain 24, 65 Hz bandwidth; 1.35 µV p-p maximum), CMRR of −110 dB minimum at 50/60 Hz, 1000 MΩ DC input impedance (lead-off detection off), 20 pF input capacitance and ±300 pA input bias current.', value: 0.14, units: 'µV rms', refs: ['ads1299'], status: 'verified' },
  { id: 'thermal-noise', section: 5, statement: 'Thermal (Johnson–Nyquist) noise of a resistance R at temperature T over bandwidth Δf has mean-square voltage 4kTRΔf, i.e. v_rms = √(4kTRΔf); for 10 kΩ, 310 K and 100 Hz this is ≈ 0.13 µV rms.', refs: ['nyquist1928'], status: 'verified', note: 'The numerical example is derived from the formula; the auditor confirmed the arithmetic.' },
  { id: 'skin-noise', section: 5, statement: 'Surface-electrode noise on skin is 1–20 µV rms depending on skin treatment and subject, originates mainly at the electrolyte–skin interface (electrodes face-to-face in gel give < 1 µV rms once stabilised), is considerably higher than the thermal noise of the electrode impedance, and scales inversely with the square root of electrode area.', range: [1, 20], units: 'µV rms', refs: ['huigen2002'], status: 'verified' },
  { id: 'averaging', section: 5, statement: 'Averaging N trials improves the signal-to-noise ratio of an event-related potential in proportion to √N (noise falls as SD/√N); typical components are a few microvolts (error-related negativity difference 5–15 µV, lateralised readiness potential 1–4 µV) while single-trial noise is much larger than the signal.', refs: ['luck2022', 'boudewyn2018'], status: 'verified', note: 'The √N statement was verified in Luck’s open textbook (ch. 6 §6.7); the component amplitudes were verified in the Boudewyn et al. author manuscript (eScholarship) after the auditor could not access it.' },
  { id: 'motion-artifact', section: 5, statement: 'No satisfying quantitative model exists for the triboelectric charge generated by friction at the electrode–skin interface (transversal motion is modelled to first order as a change in coupling impedance); capacitive non-contact electrodes can need more than 10–15 s to recover after a motion-induced overload; mains current coupled into cables (10 nA p-p with 20 kΩ electrodes and 50% differences in current and impedance) gives ~200 µV p-p of interference.', refs: ['chi2010', 'mettingvanrijn1990'], status: 'verified', note: 'Reworded after audit.' },
  // ───────────── section 5: electrodes ─────────────
  { id: 'chi-table', section: 6, statement: 'Measured coupling impedances (differential pair of closely spaced electrodes on the resting forearm; skin preparation not reported): wet Ag/AgCl gel electrode ≈ 350 kΩ ∥ 25 nF; dry metal plate ≈ 1.3 MΩ ∥ 12 nF; thin-film insulated electrode ≈ 550 MΩ ∥ 220 pF; non-contact through a cotton shirt ≈ 305 MΩ ∥ 34 pF.', refs: ['chi2010'], status: 'partially', note: 'Electrode area is not stated in the table; the site uses the values as per-cm² references for scalp electrodes (a modelling assumption).' },
  { id: 'abrasion', section: 6, statement: 'The traditional way to obtain low-noise contact is to abrade the skin to a contact resistance of 5–10 kΩ; EEG practice historically required < 5 kΩ, and unabraded saline-sponge electrodes measure about 10 kΩ.', range: [5, 10], units: 'kΩ', refs: ['chi2010', 'ferree2001'], status: 'verified' },
  { id: 'rosell', section: 6, statement: 'For gel-coated but otherwise unprepared skin over 1 cm² (thorax, leg and forehead sites), the 1 Hz skin impedance ranged from 10 kΩ to 1 MΩ across ten sites on ten subjects, falling to ~220 Ω at 100 kHz and ~120 Ω at 1 MHz.', range: [10e3, 1e6], units: 'Ω·cm²', refs: ['rosell1988'], status: 'verified' },
  { id: 'area-scaling', section: 6, statement: 'Contact impedance falls with effective contact area: in a finite-element model of a 1 cm × 1 cm dry electrode the 20 Hz impedance is 17.6 kΩ at full contact and about 60 kΩ (data point; ~51 kΩ by the fitted regression) when only 25% of the area makes contact, the authors naming skin pores and hair as the reasons a plate’s whole surface is not in contact; electrode noise scales as 1/√area.', value: 17.6, units: 'kΩ', refs: ['cardu2012', 'huigen2002'], status: 'verified' },
  { id: 'hair', section: 6, statement: 'Occipital scalp hair density is 124–200 hairs/cm² (65–85 follicular units/cm², 1.0–1.4 mm apart); in Caucasian women pigmented scalp hairs average ~57 µm and white hairs ~68 µm in diameter.', range: [57, 68], units: 'µm', refs: ['jimenez1999', 'vanneste2004'], status: 'verified', note: 'Reworded after audit (the two diameters are pigmented vs white hair means, not a population range).' },
  { id: 'hair-permittivity', section: 6, statement: 'No measured relative permittivity for a hair/air layer under an electrode was located; the model treats the gap as air (εr = 1) by default and exposes εr as a slider.', value: 1, refs: [], status: 'assumption' },
  { id: 'noncontact-cap', section: 6, statement: 'Non-contact electrodes are nominally described as coupling through tens of picofarads (with a non-negligible resistive component in practice); insulated electrodes in direct skin contact couple through ~300 pF (Alizadeh-Taheri et al. 1996, as reported by Chi et al.) to several nanofarads; a custom amplifier reached 50 TΩ ∥ 60 fF input impedance and worked with coupling capacitances as low as 0.5 pF; a practical active electrode has ~5 pF input capacitance, which forms a divider with the coupling capacitance unless actively shielded.', refs: ['chi2010', 'chi2011', 'alizadeh1996'], status: 'verified', note: 'Corrected after audit: the 300 pF figure is attributed to Alizadeh-Taheri et al. (1996), not Taheri et al. (1994).' },
  { id: 'haired-scalp-wet', section: 6, statement: 'Raising electrode coupling resistance lowers noise only when R exceeds 1/(ωC); for the low coupling capacitance of a gapped electrode this threshold becomes exceedingly large, which is why the review concludes that research EEG over haired scalp still requires wet electrodes.', refs: ['chi2010'], status: 'verified' },
  { id: 'ferree', section: 6, statement: 'Modern EEG amplifiers have input impedances of order 200 MΩ ∥ 10 pF; raising scalp-electrode impedance from < 10 kΩ (abraded skin) to 40 kΩ (intact skin) produced no significant amplitude change in any EEG band, 60 Hz noise was nearly independent of impedance and mismatch (≈8% non-significant increase), and by analysis impedances up to 200 kΩ give < 0.1% amplitude error.', refs: ['ferree2001'], status: 'verified', note: 'Corrected after audit to match the published abstract (< 10 kΩ; 60 Hz nearly independent of mismatch).' },
  { id: 'kappenman', section: 6, statement: 'With a high-input-impedance active-electrode system, sites left at their natural 10–190 kΩ needed about 35 trials to reach 80% power for a P3 effect versus about 12 trials for sites abraded to < 5 kΩ; the extra noise was concentrated at low frequencies (skin potentials; the spectra in their figure 4 diverge mainly below about 5 Hz and are similar above) and worse in a warm, humid room.', range: [12, 35], units: 'trials', refs: ['kappenman2010'], status: 'verified', note: 'Second audit: the “below 5 Hz” figure is read from their figure 4 rather than stated in the text, so it is now attributed to the figure.' },
  { id: 'dry-vs-wet-time', section: 6, statement: 'Dry electrodes start with higher impedance but can become comparable to wet electrodes after a few minutes as sweat accumulates; in one study (Lin et al. 2011, as reported by Lopez-Gordo et al.) wet-electrode impedance deteriorated from 5 to 15 kΩ over 5 hours after gel application while dry-electrode impedance stayed constant.', refs: ['chi2010', 'lopezgordo2014'], status: 'verified', note: 'Both statements are secondary reports.' },
  { id: 'searle', section: 6, statement: 'In a direct comparison, shielded dry and insulating electrodes picked up 40 dB and 34 dB less interference from non-stationary electric fields than wet electrodes; their motion artefacts were higher than wet electrodes at the start of trials but lower by 8.2 dB and 6.8 dB on average by the end.', refs: ['searle2000'], status: 'verified' },
  { id: 'fingered', section: 6, statement: 'Hair-penetrating fingered dry electrodes have been reported at 14–55 kΩ per finger (TiN) versus ~10 MΩ per finger for another dry sensor, and high skin-contact impedance results in much larger motion artefacts with dry sensors.', refs: ['chi2010'], status: 'verified' },
  { id: 'consumer-electrodes', section: 6, statement: 'A systematic review of low-cost consumer EEG headsets states that most use dry electrodes, naming the InteraXon Muse (dry electrodes at FPz, AF7, AF8, TP9 and TP10) and the single-channel NeuroSky MindWave (dry forehead electrode with an ear-clip reference); the Dreem sleep headband uses five dry silicone electrodes, the occipital ones carrying protrusions that reach the scalp through hair, and Bitbrain’s Diadem uses 12 dry sensors with no gel; by contrast the Emotiv EPOC X uses saline-based sensors and the Emotiv Insight semi-dry polymer sensors.', refs: ['larocco2020', 'arnal2020', 'bitbraindiadem', 'emotivepocx', 'emotivinsight'], status: 'verified', note: 'Audit: supported; the through-hair protrusions are on the Dreem’s occipital electrodes. Manufacturer pages are not peer reviewed.' },
  { id: 'electrode-noise-levels', section: 6, statement: 'Modelling choice for the traces: electrode–skin noise of 1.5 µV rms (abraded, gelled skin), 4 µV (gel on unprepared skin), 8 µV (dry plate) and 8 µV (plate over hair), with a 1/f spectrum and 1/√area scaling. Huigen et al. measured 1–20 µV rms for gelled electrodes depending on skin treatment, with noise scaling as 1/√(electrode area); the 1/f character of that noise is attributed to Huigen et al. by the Chi et al. review; Kappenman & Luck found noise elevated at low frequencies at unabraded, high-impedance sites, with spectra similar at higher frequencies. The values for dry plates and plates over hair are extrapolations.', refs: ['huigen2002', 'chi2010', 'kappenman2010'], status: 'assumption', note: 'The ordering (abraded < gel < dry) follows the cited dependence on skin treatment; the specific values are chosen, not measured. Audit: the 1–20 µV range, its dependence on skin treatment and the 1/√area scaling are in Huigen et al.’s abstract; the 1/f spectrum is only corroborated through Chi et al. 2010; the earlier “below 5 Hz” wording was a reading of Kappenman & Luck’s figure 4, not a stated number, and was removed.' },
  { id: 'amp-current-noise', section: 6, statement: 'An amplifier’s input current noise flows through the electrode impedance and appears as voltage noise iₙ·|Zₑ|; a research non-contact amplifier reached 0.05 fA/√Hz current noise and 200 nV/√Hz voltage noise, both at 1 Hz, with an input impedance of 60 fF ∥ 50 TΩ. Commercial EEG front ends such as the TI ADS1299 do not specify a current-noise density (300 pA typical input bias current), so the slider default of 1 fA/√Hz is a modelling choice.', value: 1, units: 'fA/√Hz', refs: ['chi2011', 'ads1299'], status: 'verified', note: 'Audit: both Chi et al. figures appear verbatim in the abstract, and “at 1 Hz” qualifies both (the earlier wording attached it only to the voltage noise). The 1 fA/√Hz default is an assumption.' },
  // ───────────── section 6: dimensionality ─────────────
  { id: 'iivanainen-components', section: 7, statement: 'Generalised spatial-frequency analysis of a realistic four-compartment head model: about 110 spatial-frequency components capture 99% of the scalp-EEG topography energy of the most superficial sources (versus ~280 for on-scalp MEG), requiring an EEG sensor spacing of ~2.6 cm (at least ~120 sensors); in a homogeneous single-shell model without skull or CSF the median count rises from 80 to about 290.', value: 110, refs: ['iivanainen2021'], status: 'verified', note: 'Corrected after audit (on-scalp MEG ~280; the no-skull comparison is the single-shell median 291 vs 80).' },
  { id: 'iivanainen-eigen', section: 7, statement: 'For independent, identically distributed cortical sources, 26 eigencomponents explain 99% of scalp-EEG variance (88 for on-scalp MEG); with noise, about 20 EEG samples suffice for 90% of the variance at low noise, while at high noise even 400 samples explain only ~80%. In the preprint, for a small motor-cortex region of interest only 8 EEG components had SNR above 1 with white sensor noise (4 with brain-background noise).', value: 26, range: [4, 26], refs: ['iivanainen2021', 'iivanainen2019'], status: 'verified', note: 'Corrected after audit: published value 26 (preprint 25); the region-of-interest figures appear only in the preprint and are attributed to it.' },
  { id: 'spatial-nyquist', section: 7, statement: 'Characterising the full range of spatial frequencies in scalp EEG (spherical-harmonic degree up to about 7 on a ~9 cm head) requires a minimum of 128 sensors at just under 3 cm spacing; 32 or fewer channels is a sparse montage (the authors call the estimate preliminary).', value: 128, refs: ['srinivasan1998nyquist'], status: 'verified' },
  { id: 'freeman-spectra', section: 7, statement: 'Scalp spatial power spectra measured with a 3 mm-pitch linear array peak at 0.1–0.4 cycles/cm (wavelengths of 2.5–10 cm), suggesting ~1 cm optimal spacing; a finite-element study by overlapping authors argues for a practical Nyquist of 3 cycles/cm (~3 mm spacing).', range: [0.1, 3], units: 'cycles/cm', refs: ['freeman2003', 'ramon2009'], status: 'verified' },
  { id: 'ryynanen', section: 7, statement: 'In a three-layer spherical head model, electrode arrays up to 256 channels improved inverse cortical-potential estimates only at low realistic noise; the advantage of dense arrays shrinks as noise grows, though in clinical environments at least 64 electrodes is always beneficial. Clinically, interictal-spike sources were significantly closer to the lesion with 63 than with 31 electrodes in 9 of 14 patients, rising to 11 of 14 with 123.', range: [64, 256], refs: ['ryynanen2004', 'lantz2003'], status: 'verified' },
  { id: 'ica-dipolar', section: 7, statement: 'Decomposing 71-channel EEG from 13 subjects, the best independent-component algorithm (AMICA) yielded on average 34 of 71 components (48%) with near-dipolar scalp maps (under 10% residual variance).', value: 34, refs: ['delorme2012'], status: 'verified' },
  { id: 'inverse-illposed', section: 7, statement: 'The distributed EEG inverse problem is underdetermined: the number of candidate source locations is far larger than the number of electrodes (p ≫ N), with electrode counts usually below 100.', refs: ['grech2008'], status: 'verified' },
  { id: 'cortical-neurons', section: 7, statement: 'The adult (male) human brain contains 86 ± 8 billion neurons, of which 19% (about 16 billion) are in the cerebral cortex.', value: 1.6e10, refs: ['azevedo2009'], status: 'verified' },
  { id: 'itr-2002', section: 7, statement: 'As of 2002 the best brain–computer interfaces had maximum information transfer rates of 10–25 bits per minute.', value: 25, units: 'bits/min', refs: ['wolpaw2002'], status: 'verified' },
  { id: 'itr-ssvep', section: 7, statement: 'A 40-target steady-state visual evoked potential (SSVEP) speller reached information transfer rates up to 5.32 bits/s (~319 bits/min); a later 40-class speller averaged 325 bits/min cue-guided and 199 bits/min in free spelling.', value: 5.32, units: 'bits/s', refs: ['chen2015', 'nakanishi2018'], status: 'verified' },
  { id: 'mi-classes', section: 4, statement: 'Imagined movements of the left hand, right hand, foot (both feet in the competition data) and tongue produce distinguishable sensorimotor-rhythm changes: hand-area mu desynchronises during hand imagery but is enhanced during foot and tongue imagery. These are the four motor-imagery classes of BCI Competition IV dataset 2a.', refs: ['pfurtscheller2006', 'tangermann2012'], status: 'verified', note: 'Audit: supported; wording aligned to the sources.' },
  { id: 'motor-map', section: 4, statement: 'The hand area of primary motor cortex lies on a knob of the precentral gyrus, and the mouth region of motor cortex has been localised by stereotaxic coordinates. The patch centres drawn in section 6 are the site’s own approximate coordinates, chosen to lie on that hand knob (±37, −25, 58 mm in MNI space), on the paracentral lobule next to the midline for the feet (0, −30, 72 mm) and on the ventral precentral mouth region (±55, −8, 36 mm), converted to the fsaverage head frame with MNE-Python.', refs: ['yousry1997', 'fox2001'], status: 'assumption', note: 'Audit: only the hand-knob location was verifiable from the sources; the coordinates are modelling choices, not values taken from them, and two sources that could not be checked (Homan et al. 1987; Penfield & Boldrey 1937) were dropped.' },
  { id: 'dof-control', section: 7, statement: 'People learned two-dimensional cursor control from scalp sensorimotor rhythms, and four adults learned simultaneous control of three independent EEG signals (one per dimension, from 3–4 electrodes), reaching targets in a virtual cube in 56–93% of trials, the first report of three-dimensional EEG control.', value: 3, units: 'dimensions', refs: ['wolpaw2004', 'mcfarland2010'], status: 'verified', note: 'Corrected after audit: the claim no longer asserts that three is the most dimensions ever demonstrated.' },
  { id: 'kinematics-chance', section: 7, statement: 'Linear-regression reconstruction of limb kinematics from low-frequency scalp EEG produced positive correlations that were not above the chance level estimated by randomly pairing velocity profiles with EEG from other trials (and with synthetic random data).', refs: ['antelis2013'], status: 'verified' },
  { id: 'fsaverage-bem', section: 4, statement: 'FreeSurfer’s fsaverage template (a high-resolution average cortical surface built by spherical intersubject registration) is available to MNE-Python through mne.datasets.fetch_fsaverage (downloaded on first use) together with a three-layer boundary-element head model (inner skull, outer skull, scalp; ico-4 surfaces of 5120 triangles each; file fsaverage-5120-5120-5120-bem-sol.fif), fiducials, a head–MRI transform and an ico-5 cortical source space; mne.make_bem_model defaults to conductivity = (0.3, 0.006, 0.3), i.e. brain and scalp 0.3 S/m and skull 0.006 S/m.', refs: ['mnefsaverage', 'mnebemmodel', 'mnefsaveragesrc', 'gramfort2014', 'fischl1999'], status: 'verified', note: 'Corrected after audit: files are fetched, not bundled; the file list is verified in the MNE source (mne/datasets/_fsaverage/base.py) and the layer/triangle description in Gramfort et al. 2014.' },
  { id: 'mne-bem', section: 4, statement: 'MNE computes EEG forward solutions (gain matrices) for single- or three-compartment boundary-element models using the linear collocation method of Mosher, Leahy & Lewis (1999) combined with the isolated-skull approach of Hämäläinen & Sarvas (1989); a three-compartment model is required when EEG data are present.', refs: ['gramfort2014', 'mosher1999', 'hamalainen1989'], status: 'verified', note: 'Corrected after audit: attribution of the collocation method moved to Mosher et al.; the 2013 Frontiers paper was dropped from this claim.' },
  { id: 'montages', section: 4, statement: 'The five-percent (10–5) system of Oostenveld & Praamstra (2001) extends the International 10–20 and 10–10 systems to 345 electrode positions. MNE-Python provides template montages through mne.channels.make_standard_montage, including 10–20/10–10/10–5 layouts fitted to fsaverage (fsaverage_1020/1010/1005, MNE ≥ 1.13) and the BioSemi 64/128/256 layouts (biosemi64/128/256); the available names are listed by mne.channels.get_builtin_montages().', refs: ['oostenveld2001', 'mnemontage'], status: 'verified', note: 'Corrected after audit: attribution limited to the 10–5 extension; montage names updated to MNE 1.13 (the analysis uses fsaverage_1020 and fsaverage_1005).' },
  { id: 'svd-method', section: 4, statement: 'With independent, identically distributed sources of rms moment q and white sensor noise of rms n, the scalp covariance is q²LLᵀ + n²I; its eigenvectors are the left singular vectors of the lead field L and component k has signal variance q²sₖ², so it exceeds the noise when sₖq > n. The fraction of signal variance carried by the first K components is Σₖ≤ᴋ sₖ² / Σ sₖ² (the eigencomponent criterion of Iivanainen et al.).', refs: ['iivanainen2021'], status: 'derived', note: 'Standard linear algebra applied to the lead field; the variance-fraction criterion follows Iivanainen et al.' },
  { id: 'svd-counts', section: 7, statement: 'Computed here (scripts/leadfield_svd.py, MNE-Python 1.13, fsaverage BEM, 20,484 fixed-orientation cortical sources, average reference): the number of lead-field components carrying 99% of the scalp variance of IID sources is 12 with 19 electrodes and 21–23 with 64 to 2,246 electrodes (90%: 6–7); restricting to the 14,001 sources inside a fitted sphere gives 16–18 for the realistic head and 15–16 for the sphere (64 electrodes and up).', value: 22, range: [12, 23], refs: [], status: 'derived', note: 'Our own computation; regenerate with the script. Depends on the IID-source assumption and the three-layer model without CSF.' },
  // ───────────── section 7: delays ─────────────
  { id: 'erd-timecourse', section: 8, statement: 'Before a self-paced finger movement the upper-alpha (mu) rhythm over the contralateral sensorimotor area begins to desynchronise about 1.75 ± 0.61 s before movement onset, beta power is attenuated in the 2.0 to 0.5 s before it, and after a brisk movement the beta rhythm recovers and shows a short-lasting synchronisation within 1 s. In cue-paced left/right hand motor imagery the cue-triggered motor-cortex activation starts about 300 ms after the cue and single-trial discrimination peaks about 1 s after it; the original Graz imagery BCI returned its classification within 1.5 s, and adaptive autoregressive classification was expected to carry a delay of around 1 s.', value: 1, units: 's', refs: ['pfurtscheller1989', 'stancak1996', 'pfurtscheller1996', 'pfurtscheller2010', 'pfurtscheller1997', 'pfurtscheller1998'], status: 'verified', note: 'Audit: all figures supported; the 1989 paper says “upper alpha components” (called mu here), and the 300 ms and 1 s cue-paced figures are the hybrid-BCI paper’s summary of earlier Graz data. The model’s defaults (fade begins 0.3 s after the intention, complete at 1 s) follow the cue-paced figures.' },
  { id: 'spectral-window', section: 8, statement: 'A periodogram of N samples cannot resolve spectral details closer than 1/N cycles per sample (1/T in hertz for a record of duration T), and its variance is high and does not fall as the record lengthens; averaging the periodograms of L shorter segments (the Bartlett method; Welch’s method with windowed, overlapping segments) reduces the variance by a factor L and the resolution by the same factor, so the choice of window trades resolution against variance.', refs: ['stoica2005', 'welch1967'], status: 'verified', note: 'Audit: supported (the 1/T restatement in hertz is the site’s unit conversion).' },
  { id: 'bci-windows', section: 8, statement: 'In the fastest flicker (SSVEP) spellers each selection takes 1 s, 0.5 s of stimulation plus 0.5 s for the gaze shift (60 characters/min, up to 5.32 bits/s), or 0.8 s with 0.3 s of stimulation (75 characters/min); the EEG epoch starts 0.14 s after the stimulus because of the visual pathway’s latency. The sensorimotor-rhythm BCI that reached three-dimensional control recomputed its spectrum every 50 ms from the previous 400 ms of EEG, and cue-paced motor-imagery competition data allotted 4 s of imagery per trial. Self-paced movement intention can be detected from the readiness potential about 500 ms before the movement.', value: 1, units: 's', refs: ['chen2015', 'nakanishi2018', 'mcfarland2010', 'tangermann2012', 'lew2012'], status: 'partially', note: 'Audit: the 0.5 s stimulation, 5.32 bits/s, 50 ms / 400 ms, 4 s and 500 ms figures were confirmed; the 0.5 s gaze shift, 60 characters/min and 0.14 s offset (Chen et al., Table 1 and Fig. 1C legends) and the 0.3 s stimulation, 0.8 s and 75 characters/min (Nakanishi et al., Section II.B.2) rest on the research agent’s reading of the full texts, which the auditor could not open.' },
  { id: 'p300-timing', section: 8, statement: 'The P300 peaks about 300 ms after an infrequent target stimulus (measured as the largest positive peak in a window such as 250 to 500 ms); in a row/column P300 speller with 100 ms flashes and 60 ms gaps, 15 sequences of 12 row and column flashes (30 flashes of each character) take 28.8 s per character, and the original Farwell–Donchin speller managed 2.3 characters per minute; P300 BCIs generally average several repetitions to raise accuracy, which slows them.', value: 300, units: 'ms', refs: ['fazelrezai2012', 'polich2007', 'farwell1988', 'nakanishi2018'], status: 'partially', note: 'Audit: the 300 ms, flash timings, 28.8 s and 2.3 characters/min are confirmed; the 250–500 ms measurement window rests on the research agent’s reading of Polich’s full text, which the auditor could not open; the averaging statement is from the discussion of Nakanishi et al. 2018.' },
  { id: 'readiness-potential', section: 8, statement: 'The early readiness potential (Bereitschaftspotential) begins about 2 s before a self-initiated movement and its steeper late phase about 400 ms before; in Libet’s experiment the onset of the readiness potential preceded the reported moment of conscious intention by about 350 ms for fully spontaneous acts (about 800 ms with some preplanning), and that reported moment lies only about 200 ms before the movement (as summarised by Schurger et al.).', value: 2, units: 's', refs: ['shibasaki2006', 'libet1983', 'schurger2021'], status: 'verified', note: 'Audit: supported; the 800 ms figure applies to series in which some acts were preplanned.' },
  { id: 'brain-background', section: 7, statement: 'Modelling choice: the brain’s own activity in the decoder’s band is taken as 10 µV rms per electrode by default (adjustable 1 to 30 µV), spatially correlated as independent cortical sources seen through the same lead field. The sources give only the whole signal: scalp EEG of 10–100 µV (Chi et al.) and about 100 µV on the scalp (Malmivuo & Plonsey), with no band-limited or rms figures and nothing on spatial correlation, so the in-band share and the correlation model are assumptions; 10 µV rms in a few-hertz band is at the pessimistic end of what those whole-signal figures allow.', value: 10, units: 'µV rms', range: [1, 30], refs: ['chi2010', 'malmivuo1995'], status: 'assumption', note: 'Audit (batch 12): both sources support the whole-signal amplitude (Chi 2010 section II; Malmivuo & Plonsey section 13.1) and nothing more; the default is flagged as pessimistic, and the slider spans the range.' },
  { id: 'window-samples', section: 7, statement: 'A band of width B observed for T seconds carries about 2BT independent numbers (Shannon’s 2TW), so a detector that knows the waveform gains about √(2BT) in amplitude SNR by averaging over the window: √6 ≈ 2.45 for a 3 Hz band over 1 s. This is the upper, coherent gain; an energy detector that reads band power without knowing the phase gains about √(BT) on power SNR. The periodogram’s resolution of 1/T and its variance, which does not fall with record length without averaging, are the spectral-estimation side of the same fact.', value: 2.45, refs: ['shannon1949', 'stoica2005', 'welch1967'], status: 'derived', note: 'Audit (batch 12): arithmetic right; the 2BT count is Shannon 1949 section II, and Stoica & Moses give the resolution (eq. 2.4.18) and the inconsistency of the periodogram (section 2.4.4), not the √(2BT) gain itself; the coherent-versus-energy-detector caveat was added at the auditor’s request.' },
  { id: 'mi-bitrate', section: 7, statement: 'Four-class motor imagery in BCI Competition IV dataset 2a reached a mean kappa of 0.57 for the winning algorithm, an accuracy of about 0.68, with 4 s of imagery per trial; Wolpaw’s information-transfer formula gives 0.58 bits per trial, about 0.15 bits/s of imagery time (about 0.07 bits/s over the whole 8 s trial). The kappa is the peak of a time course for the winning algorithm, not a typical user.', value: 0.15, units: 'bits/s', refs: ['tangermann2012', 'wolpaw2002'], status: 'derived', note: 'Audit (batch 12): kappa 0.57 confirmed (Tangermann 2012 section 5.5, table 3; Ang et al. report 0.569), the formula confirmed in Wolpaw 2002 figure 4; recomputed as 0.582 bits per trial, so 0.59 became 0.58, and the whole-trial rate and the peak-value caveat were added.' },
  { id: 'intracortical', section: 7, statement: 'For contrast, intracortical interfaces have reached 90 characters/min (handwriting, 94.1% raw accuracy), 62 words/min (speech, 9.1% word error on a 50-word vocabulary) and grid-task throughputs of 1.4–3.7 bits/s across three participants on a 6 × 6 grid (4.2 bits/s for one participant on a 9 × 9 grid).', refs: ['willett2021', 'willett2023', 'pandarinath2017'], status: 'verified' },
  // --- added with the section 7 rebuild, the section 4 subtitle check and the blink width (research topics 7 and 9) ---
  { id: 'area-sizes', section: 4, statement: 'Body-part areas of sensorimotor cortex differ in size, following innervation rather than body size: direct stimulation of the precentral gyrus in 100 awake patients found the hand and face/mouth zones proportionally much larger than their body volume, and the authors conclude that the tongue’s representation is at least as large as the hand’s; in primary somatosensory cortex the largest fingertip activation cluster per subject was 335–1340 mm² against 7.8–200 mm² for the foot (fMRI, six adults; the total fingertip-correlated area was (12 ± 5) cm²). Penfield and Boldrey’s original 1937 homunculus was scaled by length along the central sulcus, not by area (textbooks later read its proportions as areas), and that first version exaggerated the tongue, which Penfield corrected in 1950.', refs: ['roux2020', 'willoughby2021', 'catani2017', 'penfield1937'], status: 'verified', note: 'Corrected after audit (batch 13): the fingertip and foot figures are now like for like (largest single cluster), the tongue size is the authors’ conclusion, and the exaggerated tongue is the 1937 drawing’s, corrected in 1950 (Catani). Roux read from the accepted manuscript.' },
  { id: 'own-rhythm', section: 4, statement: 'Each sensorimotor area can carry its own rhythm: with subdural grids the presence and blocking of the 7–11 Hz mu rhythm were specific to the body part represented under each electrode; in magnetoencephalography (MEG) the movement-related suppression and rebound of the 20 Hz rhythm follow the finger, toe and mouth representations, while the 10 Hz component stays near the hand area; on the scalp, desynchronization appears over the hand area with finger movement in every subject and, less consistently, over the foot area with toe movement, which led the authors to propose that each area has its own rhythm. The rhythms mark idling cortex: they fall when the body part moves.', refs: ['arroyo1993', 'salmelin1995', 'pfurtscheller1997b'], status: 'verified', note: 'Corrected after audit (batch 13): the foot-area effect was harder to find, the 20 Hz result is from MEG, and the area-specific rhythm is the authors’ proposal; checked from the three abstracts.' },
  { id: 'blink-width', section: 5, statement: 'In 31 subjects (62-channel EEG, right-mastoid reference) the blink peak at FP1 averaged about 160 µV (subject means 84–306 µV) and the mean blink width at FP1 was 0.197 s (subject means 0.099–0.279 s); the paper does not define how width was measured.', value: 0.197, units: 's', range: [0.099, 0.279], refs: ['guttmannflury2025'], status: 'verified', note: 'Audit (batch 13): supported, including Table 3.' },
  { id: 'erd-depth', section: 7, statement: 'How much sensorimotor-rhythm power is lost during imagery: in 20 young adults the peak desynchronization at C3 (most reactive 3 Hz band within 7–35 Hz, chosen on the contraction task and mostly in the beta range) during kinesthetic imagery of a wrist contraction was 21–89% across subjects, mean about 52–54% (actual contraction 39–92%, mean about 69–72%); in nine subjects the most reactive mu band over the hand area opposite the imagined hand lost on average about 85% of its power (single subjects 54–99%). Both are trial-averaged values in a best band, upper bounds for single windows; the site takes 50% as typical.', value: 50, units: '%', range: [21, 99], refs: ['toriyama2018', 'pfurtscheller2006'], status: 'verified', note: 'Corrected after audit (batch 13): Toriyama’s most reactive band lay at or above 13 Hz for most participants and was chosen on the contraction task; all numbers confirmed (Toriyama’s computed from its Table 1; Pfurtscheller read from the author copy).' },
  { id: 'erd-detect', section: 7, statement: 'Model of the decision: the power of band-limited Gaussian noise of bandwidth B averaged over a time T comes from 2BT independent samples and carries a fractional uncertainty of approximately 1/√(BT), whatever its level (the radiometer equation); the estimate is then gamma distributed with shape BT. Rest and imagery windows are modelled this way, with the noise in the channel added to both, and the decoder calls imagery below the threshold where the two distributions cross. The site takes B = 3 Hz, the width of the analysis band in which the measurements of claim erd-depth located the most reactive frequencies; for B = 3 Hz and T = 1 s the approximation gives ±58% (the exact value for an ideal band averaged over a 1 s boxcar is about ±53%, so the approximation is slightly pessimistic).', refs: ['condon2016', 'shannon1949', 'kay1998'], status: 'derived', note: 'Audit (batch 14): the radiometer equation and 2BT samples confirmed in Condon & Ransom section 3.6 (eqs. 3.153–3.154) and Shannon 1949; the gamma form and the arithmetic confirmed; the auditor computed the exact ±53% for BT = 3 (analytic and by simulation), added here. Kay 1998 not opened.' },
  { id: 'rhythm-fluctuation', section: 7, statement: 'Real rhythms fluctuate more than a Gaussian process of the same bandwidth: in 57 healthy adults at rest the coefficient of variation of alpha-band power across 4 s epochs was 0.58–0.76 (a stationary Gaussian rhythm in a 3 Hz band would give 0.29; part of the measured excess is slow drift over the 10 min recording), the scatter falling as the inverse square root of the amount of data averaged; in most subjects (13 of 16) alpha power bursts between high- and low-amplitude modes, a non-Gaussian fluctuation. The site’s model is therefore optimistic.', range: [0.58, 0.76], refs: ['maltez2004', 'freyer2009'], status: 'verified', note: 'Audit (batch 13): supported; Maltez checked from its abstract only; the drift and the 13 of 16 were added at the auditor’s suggestion.' },
  { id: 'window-accuracy', section: 7, statement: 'Accuracy grows with the window: classifying left- versus right-hand imagery in BCI Competition IV dataset 2a (9 subjects, common spatial patterns with cross-validated linear discriminant analysis), the median subject scored about 60% with 0.5 s windows (about 56–77% across subjects), 65% at 1 s, 71% at 2 s and 74% at 4 s (about 58–97%), read from the paper’s Figure 3. In a separate cursor task accuracy rose as trials lengthened from 1 to 4 s, and in an offline analysis of four Graz BCI users the information at the best classification time was 0.4–1.1 bits per trial, 1.25–3 s after imagery began, about 0.3–0.4 bits/s.', refs: ['miladinovic2024', 'mcfarland2003', 'schlogl2002'], status: 'verified', note: 'Corrected after audit (batch 13): the paper’s text ranges (55–70% and 75–85%) contradict its own Figure 3, so the figure’s values are given; the cursor task (McFarland 2003, abstract) and the four-user analysis (Schlögl 2002) are separate studies.' },
  { id: 'mi-overlap', section: 7, statement: 'The imagery classes are not independent: imagining one hand lowered the mu rhythm over both hemispheres in all nine subjects, more on the opposite side on average (opposite −85% and −87%, same side −72% and −65%), though not in every subject; foot or tongue imagery tended to raise the hand-area mu instead; one of the nine desynchronized every central site during all four tasks and had the lowest four-class kappa (0.30), and the authors note that tasks with very similar central desynchronization would be nearly impossible to tell apart, and that more than two mental states are very hard to discriminate with imagery-induced desynchronization alone. Group topographies of 33 untrained adults also showed bilateral mu desynchronization.', refs: ['pfurtscheller2006', 'mcfarland2000'], status: 'verified', note: 'Corrected after audit (batch 14): the ‘nearly impossible’ is the authors’ hypothetical, observed in one subject of nine as the hardest case (kappa 0.30), and contralateral dominance holds for the means, not every subject. The auditor also noticed that rows s7 to s9 of the source’s Table 2 duplicate rows s1 to s3. McFarland 2000 checked from the abstract.' },
  { id: 'task-limit', section: 7, statement: 'Combining four motor-imagery tasks and mental arithmetic into sets of 2 to 5 classes, information transfer rates in 3 subjects were 0.42–0.81 bits per trial and the best came from three-task sets, adding a fourth or fifth task did not help; the authors put the upper limit of different mental tasks for a BCI at three. Brain–computer interfaces give low-dimensional control because they can recognise only a limited number of mental tasks as separate commands.', refs: ['obermaier2001', 'yong2015'], status: 'verified', note: 'Audit (batch 14): supported; Obermaier 2001 checked from its abstract only; Yong & Menon make the low-dimensional statement about BCIs in general, so the wording was widened.' },
  { id: 'bci-inefficiency', section: 7, statement: 'BCI control fails for an estimated 15–30% of users; one group puts the share of potential users whose accuracy misses the criterion at about 20% (its own 80 naive users averaged 74% ± 17% in their first feedback session, from chance to 100%), and a review puts the share not proficient with a typical BCI at about 20%; in 54 subjects, 53.7% (the average of two sessions) fell below 70% on two-class motor imagery.', range: [15, 30], units: '%', refs: ['vidaurre2010', 'blankertz2010', 'allison2010', 'lee2019'], status: 'verified', note: 'Corrected after audit (batch 14): the 20% in Blankertz 2010 is a background figure for potential users, not a result of its 80-subject sample; the 15–30% is stated for EEG-based BCIs generally; Lee 2019’s 53.7% averages two sessions.' },
  // --- section 9: electrode count (research topic 8) ---
  { id: 'snr-electrodes', section: 9, statement: 'Computed here (src/physics/control.ts): one patch read from N electrodes spread evenly over the four-shell sphere of section 3, against the brain’s background (independent radial dipoles over the cortex sphere, a radial variant of the random-dipole model, seen through the same head) and white electrode noise, has the matched-filter SNR² = tᵀC⁻¹t, which is also the SNR of the best linear unbiased estimate of its amplitude. It is solved exactly in electrode space up to 128 electrodes and per spherical-harmonic degree above that, the degrees finer than the array resolves (l > √N − 1, since degrees up to L hold (L+1)² coefficients) counted as noise; the two agree within 1% at 128 to 256 electrodes. With 1 µV of electrode noise and 10 µV of background, a 10 nA·m patch of 10 mm radius reaches 0.43 with 64 electrodes, 0.69 with 256 and 0.90 with 100,000, against 4.9, 10 and 197 with the electrode noise alone.', refs: ['kay1998', 'demunck1992'], status: 'derived', note: 'Audit (batch 15): the method is standard and the numbers internally consistent (√N scaling of the electrode-only values, all below the ceiling); Kay 1998 and the de Munck full text were not opened, and de Munck’s model has dipoles of every orientation, so the radial version is called a variant.' },
  { id: 'electrode-ceiling', section: 9, statement: 'Computed here: with the whole scalp potential known exactly, the head’s transfer cancels, because the patch and the background pass through the same head, and the SNR reaches a ceiling set by the background sources under the patch’s own footprint, SNR² = Q² Σ (2l+1) g_l² / β (g_l the disc’s smoothing per degree, β the background density in the site’s normalisation). For 10 nA·m over a 10 mm radius against 10 µV of background the ceiling SNR is 0.99, and halving the radius doubles it. Grover & Venkatesh argue that with brain noise as the dominant noise source, the number of sensors at which localization stops improving could be quite high; in this model the approach to the ceiling is slow when the electrode noise is low.', refs: ['grover2017'], status: 'derived', note: 'Audit (batch 15): the derivation was confirmed (the factor 4π depends on how β is normalised); the auditor could not open Grover & Venkatesh, so the attributed statement was checked by hand afterwards in the authors’ preprint (section III-B, caption of figure 7).' },
  { id: 'grover-nyquist', section: 9, statement: 'Re-deriving the spatial Nyquist analysis, Grover & Venkatesh estimate that capturing 99% of the scalp signal’s energy needs at least 289 to 361 sensors (578 for the 289-sensor case with twofold oversampling), and in noiseless simulations source resolution kept improving up to 6,252 sensors; 10,000 electrodes on the head sit about 3 mm apart.', range: [289, 361], refs: ['grover2017'], status: 'verified', note: 'Audit (batch 14): supported against the authors’ May 2016 preprint; the published text was not accessible.' },
  { id: 'brain-noise', section: 9, statement: 'Below about 100 Hz the signal-to-noise ratio of scalp recordings depends practically only on background activity generated by the cortex; amplifier noise and the thermal noise of the interelectrode resistance dominate only at a few hundred hertz and above (measured with a high-resolution EEG setup). The background can be modelled as randomly distributed cortical dipoles in a spherical head, giving a spatial covariance that depends on electrode distance (the alpha rhythm itself is better described by a fixed dipole), and measured background is well fitted by such distance-dependent covariance models.', refs: ['scheer2006', 'demunck1992', 'huizenga2002'], status: 'verified', note: 'Audit (batch 14): supported from the three abstracts; wording narrowed to the sources’ conditions.' },
  { id: 'evoked-channels', section: 9, statement: 'Evoked responses: a P300 speller gained nothing significant from 13 electrodes added to a set of 6, and more than 8 electrodes gave small gains or losses depending on the classifier; flicker (frequency and phase) decoding no longer differed between 9 and 66 parieto-occipital electrodes once more than 0.2 s of data was used, while decoding where the user fixated kept gaining up to 66; over occipital cortex, four-class visual-category decoding rose from 57% with about 9 electrodes to 73% with 464 (4 subjects); in simulations the minimum-norm source-localization error fell from 27 mm with 32 channels to 21, 20 and 18 mm with 64, 128 and 256 (whole-head montages), the last step called modest.', refs: ['krusienski2008', 'hoffmann2008', 'ming2026', 'schreiner2026', 'song2015'], status: 'verified', note: 'Corrected after audit (batch 15): the localization errors are the minimum-norm values of a simulation (another inverse method in the same table gives far smaller errors); all other numbers confirmed in the full texts.' },
  { id: 'mi-channels', section: 9, statement: 'Motor-imagery decoders peak with 10 to 50 well-placed channels: in 80 users recorded with 119 channels the best of 13 fixed montages had 48 channels, and montages of 8 to 32 were not significantly worse when few training trials were available; on a 118-channel dataset a mean of 22.6 selected channels scored 82.3% against 73.6% with all 118; predicted error stayed at 3–4% from 52 channels down to about 14; a review relays that the number can be reduced to 10 to 20 without significant loss.', range: [10, 50], refs: ['sannelli2010', 'arvaneh2011', 'popescu2007', 'blankertz2008'], status: 'verified', note: 'Audit (batch 15): supported; Sannelli checked from its abstract, Popescu’s values read from its Figure 2a (about 4% at 14 channels), Blankertz 2008 relays another study.' },
  { id: 'calibration-cost', section: 9, statement: 'A decoder that learns its spatial weights needs the channel covariance, which is hard to estimate in high-dimensional sensor spaces, so shrinkage regularisation is used; for an adaptive array that estimates the noise covariance from K independent, signal-free samples of N channels, the expected output SNR relative to the optimum is (K + 2 − N)/(K + 1), so K = 2N − 3 samples give an average loss of a factor of two (3 dB). A band B hertz wide gives at most 2B independent samples per second (exactly 2B for white noise), so 2N samples take at least N/B seconds.', refs: ['blankertz2011', 'reed1974', 'shannon1949'], status: 'partially', note: 'Audit (batch 15): the formula and arithmetic are right, but the original Reed–Mallett–Brennan paper could not be opened; the formula was confirmed through a later review that cites it. The conditions (signal-free training samples; at most 2B samples per second for coloured EEG) were added. Blankertz 2011 checked from its abstract.' },
  { id: 'eeg-systems', section: 9, statement: 'Electrode counts of real systems: the International 10–20 system has 21 electrode positions; research caps go up to 256 electrodes (BioSemi 16 to 256; EGI nets 32 to 256), commercial high-density systems mostly using 160 to 256 channels; ultra-high-density grids reach 1,024 channels 8.6 mm apart; consumer headsets range from a single channel (NeuroSky MindWave) to 14 (Emotiv EPOC X).', refs: ['acharya2016', 'biosemicap', 'egiges', 'lee2022', 'gtecpangolin', 'larocco2020', 'emotivepocx'], status: 'verified', note: 'Corrected after audit (batch 15): the auditor could not verify the 10–20 count in Oostenveld & Praamstra (paywalled), so it is now cited to the American Clinical Neurophysiology Society guideline (‘21 electrode positions in the 10-20 system’), checked by hand; the single-channel lower bound is cited to the low-cost headset review of claim consumer-electrodes; a stray fragment was removed from the Emotiv citation.' },
  { id: 'blink-mechanism', section: 5, statement: 'A blink’s deflection on the scalp is not a muscle signal: blink potentials arise as the eyelids slide down over the cornea, which sits at a steady potential of about +13 mV relative to the forehead, so that the lid acts like a sliding electrode short-circuiting the cornea to the scalp, and the artifact is mostly frontal; the contribution of the eye muscles, including their activity during blinking, has been called negligible. Blink artifacts seen in intracranial recordings have been described as resembling these ocular components, which arise from the corneoretinal potential and the eye’s changing conductivity rather than muscle depolarization. In magnetoencephalography (MEG), voluntary blinks produce a large slow wave lasting about 400 ms and a small burst above 30 Hz at blink onset; the authors attribute the activity around the eyes to a combination of muscle contraction and eyelid currents.', refs: ['lins1993', 'picton2000', 'plochl2012', 'kovach2011', 'bardouille2006'], status: 'verified', note: 'Corrected after audit (batch 16): no source caps the muscle share at a small burst, so the MEG result is now reported as found, and the negligible ocular-muscle contribution is attributed to Plöchl et al.; Lins, Picton and Bardouille checked from their abstracts; Kovach et al. summarise the intracranial study of Ball et al. 2009.' },
  { id: 'mi-matrix', section: 7, statement: 'Mean change of mu-band power during cued motor imagery at the three central electrodes, from nine subjects, each in their most reactive band and relative to a 1 s rest reference (per cent; ± the standard deviation across subjects): left hand C3 −64.6 ± 25.2, Cz −56.8 ± 14.7, C4 −86.7 ± 9.4; right hand C3 −84.7 ± 16.8, Cz −58.3 ± 18.4, C4 −71.6 ± 18.8; foot C3 +89.3 ± 116.8, Cz −21.3 ± 65.1, C4 +112.7 ± 140.8; tongue C3 +145.2 ± 128.9, Cz +107.0 ± 66.8, C4 +133.6 ± 160.5. The authors note that C3 and C4 overlie approximately the hand representation areas.', refs: ['pfurtscheller2006'], status: 'unverified', note: 'Read from Table 1 of the author copy (the table is an image); the ERD values are trial averages in each subject’s most reactive 2 Hz band, chosen from significance maps, so they are upper bounds for a fixed-band decoder.' },
];

export const claimById = new Map(CLAIMS.map((c) => [c.id, c]));
